// Semantic meaning remains independent of collision kind and visible treatment.
export const ARTWORK_ROLES={platform:'#91e8c1',background:'#6b9fe8',decoration:'#f5a15c'};
export function semanticRole(object){if(Object.hasOwn(ARTWORK_ROLES,object.role))return object.role;const color=String(object.color||'').toLowerCase();if(color===ARTWORK_ROLES.background)return'background';if(color===ARTWORK_ROLES.decoration)return'decoration';if(color===ARTWORK_ROLES.platform)return'platform';return object.kind==='decor'?'decoration':'platform'}
function artSnapshot(object){return{id:object.id,role:semanticRole(object),kind:object.kind,x:object.x,y:object.y,w:object.w,h:object.h,rotation:object.rotation||0,inset:object.inset||0,flip:!!object.flip}}
function artSameGeometry(a,b){const current=artSnapshot(a),snapshot=artSnapshot(b);return Object.keys(current).every(key=>typeof current[key]==='number'?Math.abs(current[key]-snapshot[key])<1e-8:current[key]===snapshot[key])}
function artHash(value){let a=2166136261,b=0x9e3779b9;for(let i=0;i<value.length;i++){a=Math.imul(a^value.charCodeAt(i),16777619);b=Math.imul(b^value.charCodeAt(i),2246822519)}return(a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0')}
function artReferenceMetadata(asset){return{...(asset.sheet?{sheet:structuredClone(asset.sheet)}:{}),...(asset.type?{type:asset.type}:{}),...(asset.spriteSheet?{spriteSheet:structuredClone(asset.spriteSheet)}:{}),...(asset.referenceSelection?{referenceSelection:structuredClone(asset.referenceSelection)}:{})}}
function artMetadataHash(asset){return artHash(JSON.stringify(artReferenceMetadata(asset)))}
function artObjects(project,objectIds){if(objectIds!==undefined&&(!Array.isArray(objectIds)||!objectIds.length))throw Error('Choose at least one shape.');const ids=objectIds?new Set(objectIds):null;if(ids&&ids.size!==objectIds.length)throw Error('Choose each shape only once.');if(ids)for(const id of ids)if(!project.objects.some(o=>o.id===id))throw Error('A selected shape no longer exists.');const objects=project.objects.filter(o=>(!ids||ids.has(o.id))&&!o.collisionOnly);if(!objects.length)throw Error('Sketch a shape before applying artwork.');if(ids&&objects.some(o=>o.locked))throw Error('Unlock the selected shapes before applying artwork.');return objects.filter(o=>!o.locked)}
function artBounds(objects){if(!objects.length)throw Error('Unlock a shape before applying artwork.');const boxes=objects.map(objectBounds),x=Math.floor(Math.min(...boxes.map(b=>b.x))),y=Math.floor(Math.min(...boxes.map(b=>b.y)));return{x,y,w:Math.max(1,Math.ceil(Math.max(...boxes.map(b=>b.x+b.w)))-x),h:Math.max(1,Math.ceil(Math.max(...boxes.map(b=>b.y+b.h)))-y)}}
