// Multiple selected sheets are committed as one project mutation / undo step.
export function applyAssetSheet(raw,options={}){if(options.assetId&&options.assetIds)throw Error('Supply one sheet ID or an array of sheets.');if(!options.assetIds)return artApplyOne(raw,options);const initial=validateProject(raw),ids=options.assetIds;if(!Array.isArray(ids)||!ids.length||ids.length>2000||new Set(ids).size!==ids.length)throw Error('Choose at least one distinct asset sheet.');const allSheets=ids.map(id=>{const asset=initial.assets.find(a=>a.id===id);if(!asset)throw Error('A selected asset sheet no longer exists.');return asset}),sheets=allSheets.filter(a=>a.spriteSheet?.type!=='character');if(!sheets.length)throw Error('Choose environment sheets to apply. Character sheets remain generation references.');const selected=artObjects(initial,options.objectIds),byRole=new Map();for(const sheet of sheets){const role=sheet.sheet?.role||'platform';if(!byRole.has(role))byRole.set(role,[]);byRole.get(role).push(sheet)}let project=initial,total=0;const applied=[];for(const [role,group] of byRole){const objects=selected.filter(o=>semanticRole(o)===role);for(let i=0;i<group.length;i++){const objectIds=objects.filter((_,index)=>index%group.length===i).map(o=>o.id);if(!objectIds.length)continue;const result=artApplyOne(project,{...options,assetId:group[i].id,objectIds});project=result.project;total+=result.details.objects;applied.push(group[i].id)}}if(!total)throw Error('No unlocked shapes match the selected sheets.');return{project,details:{assetIds:applied,objects:total,geometryPreserved:true,reusedSource:true}}}

function artTargetOptions(target){return target.kind==='sheet'?{}:target.kind==='group'?{groupId:target.groupId}:{frameIds:target.frameIds}}
function artTargetFingerprint(asset,target){const meta=asset.spriteSheet,ids=new Set(target.frameIds),groups=meta.groups.map(g=>({...g,frameIds:g.frameIds.filter(id=>ids.has(id))})).filter(g=>g.frameIds.length);return artHash(JSON.stringify({id:asset.id,w:asset.w,h:asset.h,type:meta.type,source:meta.source||'sheet',cellWidth:meta.cellWidth,cellHeight:meta.cellHeight,rows:meta.rows,cols:meta.cols,gutterX:meta.gutterX,gutterY:meta.gutterY,marginX:meta.marginX,marginY:meta.marginY,grouping:meta.grouping,groups,frames:target.frameIds.map(id=>meta.frames.find(f=>f.id===id))}))}
function artAssetInstructions(request){return`Create artwork for this existing ${request.target.kind==='group'?'animation strip':request.target.kind==='frames'?'frame selection':'asset sheet'}. Return ONE PNG with the same ${request.width} × ${request.height} layout and aspect ratio. Follow every frame rectangle in placements and retain its ordering, shared origin, transparent padding and animation continuity. Do not add, remove, reorder or recenter frames. Treat selected references as a related visual family. Pixel Mill binds each returned rectangle to its original stable frame ID and keeps the original pixels, grouping and other frames unchanged. Request ID: ${request.id}.${request.prompt?' Visual direction: '+request.prompt:''}`}
function artAssetTarget(project,request){const asset=project.assets.find(a=>a.id===request.target.assetId);if(!asset?.spriteSheet||artTargetFingerprint(asset,request.target)!==request.targetHash||artSourceHash(project,asset,request.target.frameIds)!==request.sourceHash)throw Error('The target frames changed since this request. Prepare a fresh asset artwork request.');return asset}
export async function getAssetArtworkRequest(raw,{requestId,includeImages=true}={}){const project=validateProject(raw),request=project.assetRequests?.find(r=>r.id===requestId);if(!request)throw Error('Asset artwork request not found.');const asset=artAssetTarget(project,request),references=await artReferences(project,request,includeImages),raster=includeImages?await exportSpriteSheet(asset,artTargetOptions(request.target),project.assets):null;return{...structuredClone(request),...(raster?{map:raster.src}:{}),references,targetMetadata:{name:asset.name,type:asset.spriteSheet.type,cellWidth:asset.spriteSheet.cellWidth,cellHeight:asset.spriteSheet.cellHeight,groups:asset.spriteSheet.groups.map(g=>({...g,frameIds:g.frameIds.filter(id=>request.target.frameIds.includes(id))})).filter(g=>g.frameIds.length)},instructions:artAssetInstructions(request)}}
export async function prepareAssetArtwork(raw,{assetId,groupId,frameIds,assetIds,id,prompt='',includeImages=true}={}){
 const project=validateProject(raw);let asset=project.assets.find(a=>a.id===assetId);if(!asset||asset.hidden)throw Error('Choose an asset sheet or family to iterate.');if(groupId&&frameIds)throw Error('Choose one group or an explicit frame selection.');if(!asset.spriteSheet){asset=await groupSpriteSheet(asset,{cellWidth:asset.w,cellHeight:asset.h,rows:1,cols:1,sheetType:asset.sheet?'environment':'character'});project.assets[project.assets.findIndex(a=>a.id===assetId)]=asset}
 if(frameIds!==undefined&&(!Array.isArray(frameIds)||!frameIds.length||new Set(frameIds).size!==frameIds.length))throw Error('Select distinct target frames.');const options=groupId?{groupId}:frameIds?{frameIds}:{};const layout=spriteSheetLayout(asset,options,project.assets),resolved=layout.placements.map(p=>p.frameId),target={assetId,kind:groupId?'group':frameIds?'frames':'sheet',...(groupId?{groupId}:{}),frameIds:resolved};if(!resolved.length)throw Error('Choose a target with at least one frame.');const chosen=assetIds??artDefaultReferences(project).filter(a=>a.id!==assetId||a.referenceSelection).map(a=>a.id);if(!Array.isArray(chosen)||chosen.length>2000||new Set(chosen).size!==chosen.length)throw Error('Choose distinct visual reference families.');const references=chosen.map(id=>{const ref=project.assets.find(a=>a.id===id);if(!ref||ref.hidden)throw Error('Visual reference family not found.');return ref}),requestId=id||'asset-art-'+crypto.randomUUID();if(project.assetRequests?.some(r=>r.id===requestId))throw Error('Asset artwork request ID already exists.');if((project.assetRequests?.length||0)>=100)throw Error('Asset artwork request history is full.');const request={id:requestId,format:'pixel-mill-asset-artwork',version:1,target,targetHash:artTargetFingerprint(asset,target),sourceHash:artSourceHash(project,asset,resolved),width:layout.w,height:layout.h,placements:layout.placements.map(p=>({frameId:p.frameId,x:p.x,y:p.y,w:p.w,h:p.h})),assetIds:chosen,assetHashes:references.map(a=>artRefHash(project,a)),metadataHashes:references.map(artMetadataHash),prompt:String(prompt).slice(0,4000),status:'prepared'};project.assetRequests=[...(project.assetRequests||[]),request];const clean=validateProject(project);return{project:clean,request:await getAssetArtworkRequest(clean,{requestId,includeImages}),details:{requestId,assetId,frames:resolved.length,width:layout.w,height:layout.h,references:chosen.length}};
}
export async function applyAssetArtwork(raw,{requestId,dataUrl,id,name='Asset artwork'}={}){
 const project=validateProject(raw),request=project.assetRequests?.find(r=>r.id===requestId);if(!request)throw Error('Asset artwork request not found.');if(request.status==='applied')throw Error('This asset artwork request is already applied. Undo it or prepare another.');const target=artAssetTarget(project,request);if(!dataUrl)throw Error('Supply the returned asset PNG.');const image=await decodePNG(pngBytes(dataUrl)),aspectError=Math.abs(image.w/request.width-image.h/request.height);if(aspectError>1/Math.max(request.width,request.height)+1e-9)throw Error(`Returned asset artwork must preserve the ${request.width} × ${request.height} aspect ratio.`);const assetId=id||'asset-artwork-'+crypto.randomUUID();if(project.assets.some(a=>a.id===assetId))throw Error('Artwork source ID already exists.');const replacements=request.placements.map(p=>{const x=Math.round(p.x/request.width*image.w),y=Math.round(p.y/request.height*image.h),w=Math.round((p.x+p.w)/request.width*image.w)-x,h=Math.round((p.y+p.h)/request.height*image.h)-y;if(w<1||h<1)throw Error('Returned image is too small to preserve all target frames.');return{frameId:p.frameId,artwork:{asset:assetId,x,y,w,h}}});project.assets.push({id:assetId,name,w:image.w,h:image.h,src:dataUrl,hidden:true,parentAssetId:target.id});for(const replacement of replacements)target.spriteSheet.frames.find(f=>f.id===replacement.frameId).artwork=replacement.artwork;request.status='applied';request.appliedAsset=assetId;return{project:validateProject(project),details:{requestId,assetId:target.id,sourceAssetId:assetId,frameIds:request.target.frameIds,frames:request.target.frameIds.length,originalSourcesPreserved:true}};
}
